+                        "client's channel buffer should be in range [" + minBufSize + "," + maxBufSize + "], got " + bufSize,
+                        bufSize >= minBufSize && bufSize <= maxBufSize
+                    );
+                });
+                handler.readBytes(partSize);
+            }
+            assertTrue(handler.stream.hasLast());
+        }
+    }
