+            comp.addComponent(true, buf);
+            comp.addComponent(true, chunk);
+            buf = comp;
+        }
+    }
+
+    // visible for test
+    Channel channel() {
+        return channel;
+    }
+
+    // visible for test
+    ByteBuf buf() {
+        return buf;
+    }
+
+    // visible for test
+    boolean hasLast() {
+        return hasLast;
+    }
+
+    private void send() {
