+
+                @Override
+                public void addItems(List<DocWriteRequest<?>> items, Releasable releasable, Runnable nextItems) {
+                    releasable.close();
+                    docs.addAll(items);
+                }
+
+                @Override
+                public void lastItems(List<DocWriteRequest<?>> items, Releasable releasable, ActionListener<BulkResponse> listener) {
+                    releasable.close();
+                    docs.addAll(items);
+                    isLast.set(true);
+                }
+            }
+        );
