+        returnType = "boolean",
+        preview = true,
+        description = "Performs a query string query. Returns true if the provided query string matches the row.",
+        examples = { @Example(file = "qstr-function", tag = "qstr-with-field") }
+    )
+    public QueryStringFunction(
